import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { pathToFileURL } from 'node:url'

const REPO = '/home/ian/hello-world'
const PORT = 3100
const URL = `http://127.0.0.1:${PORT}`
const SHOTS = '/tmp/hello-shots'
const WORK = mkdtempSync(join(tmpdir(), 'hello-e2e-'))
const DATA_FILE = join(WORK, 'data', 'hello.json')

const mod = await import(
  pathToFileURL('/home/ian/.local/share/mise/installs/npm-playwright/1.63.0/node_modules/playwright/index.js').href
)
const { chromium } = mod.default ?? mod

const results = []
const consoleMessages = []
const pageErrors = []
const dialogs = []
let serverLog = ''

function check(name, ok, detail = '') {
  results.push({ name, ok, detail })
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? ` — ${detail}` : ''}`)
}
function fatal(name, error) {
  check(name, false, String(error?.stack ?? error))
}

function track(page) {
  page.on('console', (msg) => {
    const entry = `[${msg.type()}] ${msg.text()}`
    consoleMessages.push(entry)
  })
  page.on('pageerror', (error) => pageErrors.push(String(error)))
  page.on('dialog', async (dialog) => {
    dialogs.push(dialog.message())
    await dialog.dismiss()
  })
  return page
}

let proc = null
async function startServer() {
  proc = spawn(process.execPath, ['main.js'], {
    cwd: REPO,
    env: { ...process.env, PORT: String(PORT), DATA_FILE },
    stdio: ['ignore', 'pipe', 'pipe'],
  })
  proc.stdout.on('data', (d) => { serverLog += d })
  proc.stderr.on('data', (d) => { serverLog += d })
  const deadline = Date.now() + 5000
  while (!serverLog.includes('Editing at')) {
    if (proc.exitCode !== null) throw new Error(`server exited early (${proc.exitCode}): ${serverLog}`)
    if (Date.now() > deadline) throw new Error(`server did not start: ${serverLog}`)
    await new Promise((r) => setTimeout(r, 50))
  }
  return serverLog.trim()
}
async function stopServer() {
  if (!proc) return
  const exited = new Promise((r) => proc.once('exit', r))
  proc.kill('SIGTERM')
  await Promise.race([exited, new Promise((r) => setTimeout(r, 3000))])
  proc = null
}

async function statusIs(page, prefix, timeout = 2000) {
  await page.waitForFunction(
    (p) => (document.querySelector('#status')?.textContent ?? '').startsWith(p),
    prefix,
    { timeout },
  )
}

async function typeReplacer(page, text) {
  await page.click('#text')
  await page.keyboard.press('Control+a')
  await page.keyboard.type(text)
}

async function scrollCheck(label, page) {
  const { scrollWidth, clientWidth } = await page.evaluate(() => ({
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
  }))
  check(`no horizontal scroll (${label})`, scrollWidth <= clientWidth, `scrollWidth=${scrollWidth} clientWidth=${clientWidth}`)
}

try {
  const startupLine = await startServer()
  console.log(`server: ${startupLine}`)

  const browser = await chromium.launch({
    headless: true,
    // The cached Chromium build (1228) predates what playwright 1.63 bundles,
    // so the executable is addressed explicitly instead of by build revision.
    executablePath: '/home/ian/.cache/ms-playwright/chromium-1228/chrome-linux64/chrome',
  })
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } })
  const page = track(await context.newPage())

  // 1. first load, fresh data file
  await page.goto(URL, { waitUntil: 'load' })
  await statusIs(page, 'Type to edit')
  check('1. GET / shows "hello world" on a fresh store', (await page.textContent('#text')) === 'hello world',
    `#text = ${JSON.stringify(await page.textContent('#text'))}`)
  check('1b. #text is contenteditable', await page.getAttribute('#text', 'contenteditable') === 'plaintext-only')
  await page.screenshot({ path: join(SHOTS, 'desktop-1440.png') })
  await scrollCheck('desktop 1440 idle', page)

  // 3. click, select all, type
  await typeReplacer(page, 'hey you')
  await page.screenshot({ path: join(SHOTS, 'desktop-focus.png') })
  let savedOk = true
  try {
    await statusIs(page, 'Saved', 2000)
  } catch {
    savedOk = false
  }
  check('3. editing shows immediate change and status reaches "Saved" ≤2s', savedOk,
    `#text=${JSON.stringify(await page.textContent('#text'))} status=${JSON.stringify(await page.textContent('#status'))}`)
  check('3b. DOM updates immediately while typing', (await page.textContent('#text')) === 'hey you')

  // 4. on-disk artifact
  const disk = readFileSync(DATA_FILE, 'utf8')
  check('4. data file on disk literally contains "hey you"', disk === 'hey you', `file = ${JSON.stringify(disk)}`)

  // 5. reload
  await page.reload({ waitUntil: 'load' })
  await statusIs(page, 'Type to edit')
  check('5. text survives a page reload', (await page.textContent('#text')) === 'hey you',
    `#text = ${JSON.stringify(await page.textContent('#text'))}`)

  // 6. server restart
  await stopServer()
  const restartLine = await startServer()
  await page.goto(URL, { waitUntil: 'load' })
  await statusIs(page, 'Type to edit')
  check('6. text survives a server restart', (await page.textContent('#text')) === 'hey you',
    `#text = ${JSON.stringify(await page.textContent('#text'))}; ${restartLine}`)

  // 7. fresh browser profile (new context)
  const ctx2 = await browser.newContext({ viewport: { width: 1440, height: 900 } })
  const p2 = track(await ctx2.newPage())
  await p2.goto(URL, { waitUntil: 'load' })
  await statusIs(p2, 'Type to edit')
  check('7. text appears in a fresh browser context/profile', (await p2.textContent('#text')) === 'hey you',
    `#text = ${JSON.stringify(await p2.textContent('#text'))}`)
  await ctx2.close()

  // 8. keyboard-only path from about:blank
  const kb = track(await browser.newContext({ viewport: { width: 1440, height: 900 } }).then((c) => c.newPage()))
  await kb.goto('about:blank')
  await kb.goto(URL, { waitUntil: 'load' })
  await statusIs(kb, 'Type to edit')
  await kb.keyboard.press('Tab')
  const focusedId = await kb.evaluate(() => document.activeElement?.id ?? null)
  check('8. Tab reaches #text from a fresh page', focusedId === 'text', `activeElement.id = ${focusedId}`)
  await kb.keyboard.type('!')
  check('8b. typing after Tab-focus changes the greeting', (await kb.textContent('#text')) === 'hey you!',
    `#text = ${JSON.stringify(await kb.textContent('#text'))}`)
  await typeReplacer(kb, 'hey you')
  await statusIs(kb, 'Saved', 2000)
  await kb.context().close()

  // 9. mobile viewport
  const mob = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
  const mp = track(await mob.newPage())
  await mp.goto(URL, { waitUntil: 'load' })
  await statusIs(mp, 'Type to edit')
  await mp.screenshot({ path: join(SHOTS, 'mobile-390.png') })
  await scrollCheck('mobile 390', mp)
  check('9b. mobile shows the persisted text', (await mp.textContent('#text')) === 'hey you')
  await mob.close()

  // 9c/10. reduced motion
  const rm = await browser.newContext({ viewport: { width: 1440, height: 900 }, reducedMotion: 'reduce' })
  const rp = track(await rm.newPage())
  await rp.goto(URL, { waitUntil: 'load' })
  await statusIs(rp, 'Type to edit')
  await rp.screenshot({ path: join(SHOTS, 'desktop-reduced-motion.png') })
  const anim = await rp.evaluate(() => getComputedStyle(document.querySelector('.blob')).animationName)
  check('10. prefers-reduced-motion disables blob animation', anim === 'none', `animation-name = ${anim}`)
  const textAnim = await rp.evaluate(() => getComputedStyle(document.querySelector('#text')).animationName)
  check('10b. prefers-reduced-motion disables headline animation', textAnim === 'none', `animation-name = ${textAnim}`)
  await rm.close()

  // 11. stored markup is rendered as text, never executed
  const PAYLOAD = '<img src=x onerror=alert(1)>'
  await typeReplacer(page, PAYLOAD)
  await statusIs(page, 'Saved', 2000)
  const rendered = await page.textContent('#text')
  const imgCount = await page.evaluate(() => document.querySelectorAll('img').length)
  check('11. markup edit is displayed literally', rendered === PAYLOAD, `#text = ${JSON.stringify(rendered)}`)
  check('11b. no <img> element was created by the edit', imgCount === 0, `img elements = ${imgCount}`)
  const disk2 = readFileSync(DATA_FILE, 'utf8')
  check('11c. markup edit is stored literally on disk', disk2 === PAYLOAD, `file = ${JSON.stringify(disk2)}`)
  await page.reload({ waitUntil: 'load' })
  await statusIs(page, 'Type to edit')
  check('11d. markup edit still renders as text after reload', (await page.textContent('#text')) === PAYLOAD)
  check('11e. no dialog/alert fired while rendering stored markup', dialogs.length === 0,
    `dialogs = ${JSON.stringify(dialogs)}`)

  // 2. console hygiene (collected across every page for the whole run)
  const bad = consoleMessages.filter((m) => m.startsWith('[error]') || m.startsWith('[warning]'))
  check('2. zero browser console errors/warnings', bad.length === 0, `offenders = ${JSON.stringify(bad)}`)
  check('2b. zero page errors', pageErrors.length === 0, `pageerrors = ${JSON.stringify(pageErrors)}`)

  await browser.close()
} catch (error) {
  fatal('E2E run threw', error)
} finally {
  await stopServer()
}

console.log('\n--- browser console output (all messages) ---')
console.log(consoleMessages.length ? consoleMessages.join('\n') : '(empty)')
console.log('--- page errors ---')
console.log(pageErrors.length ? pageErrors.join('\n') : '(empty)')
console.log('--- dialogs ---')
console.log(dialogs.length ? dialogs.join('\n') : '(none)')
console.log('--- data file at end of run ---')
console.log(JSON.stringify(readFileSync(DATA_FILE, 'utf8')))
console.log('--- server stdout/stderr ---')
console.log(serverLog.trim() || '(empty)')
console.log(`--- data dir: ${dirname(DATA_FILE)} ---`)

const failed = results.filter((r) => !r.ok)
console.log(`\n${results.length - failed.length}/${results.length} checks passed`)
rmSync(WORK, { recursive: true, force: true })
process.exit(failed.length ? 1 : 0)

