// Throwaway visual-design verification (VALIDATION.md: not committed).
// This model cannot view images, so every step-5 visual spec item is asserted from
// computed styles, the served stylesheet, network requests and decoded screenshot pixels.
import { spawn } from 'node:child_process'
import { mkdtempSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import zlib from 'node:zlib'
import path from 'node:path'
import { pathToFileURL } from 'node:url'

const REPO = '/home/ian/hello-world'
const PORT = 3101
const URL = `http://127.0.0.1:${PORT}`
const WORK = mkdtempSync(join(tmpdir(), 'hello-vis-'))
const DATA_FILE = join(WORK, 'hello.json')

const mod = await import(
  pathToFileURL('/home/ian/.local/share/mise/installs/npm-playwright/1.63.0/node_modules/playwright/index.js').href
)
const { chromium } = mod.default ?? mod

const results = []
const check = (name, ok, detail = '') => {
  results.push({ name, ok })
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? ` — ${detail}`}`)
}

// --- minimal PNG reader (8-bit, non-interlaced) so text visibility is measurable ---
function decodePng(buf) {
  let pos = 8
  let width = 0, height = 0, colorType = 0
  const idat = []
  while (pos < buf.length) {
    const len = buf.readUInt32BE(pos)
    const type = buf.toString('ascii', pos + 4, pos + 8)
    const data = buf.subarray(pos + 8, pos + 8 + len)
    if (type === 'IHDR') {
      width = data.readUInt32BE(0); height = data.readUInt32BE(4)
      if (data[8] !== 8 || data[12] !== 0) throw new Error('unsupported PNG')
      colorType = data[9]
    } else if (type === 'IDAT') idat.push(data)
    else if (type === 'IEND') break
    pos += 12 + len
  }
  const bpp = colorType === 6 ? 4 : 3
  const stride = width * bpp
  const raw = zlib.inflateSync(Buffer.concat(idat))
  const out = Buffer.alloc(height * stride)
  const paeth = (a, b, c) => {
    const p = a + b - c
    const pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c)
    return pa <= pb && pa <= pc ? a : pb <= pc ? b : c
  }
  for (let y = 0; y < height; y++) {
    const src = y * (stride + 1)
    const filter = raw[src]
    const row = raw.subarray(src + 1, src + 1 + stride)
    const cur = y * stride
    const prev = (y - 1) * stride
    for (let x = 0; x < stride; x++) {
      const a = x >= bpp ? out[cur + x - bpp] : 0
      const b = y > 0 ? out[prev + x] : 0
      const c = x >= bpp && y > 0 ? out[prev + x - bpp] : 0
      const v = row[x]
      out[cur + x] = filter === 0 ? v
        : filter === 1 ? v + a
        : filter === 2 ? v + b
        : filter === 3 ? v + ((a + b) >> 1)
        : v + paeth(a, b, c)
    }
  }
  return { width, height, bpp, data: out }
}
function stats(img) {
  const { data, bpp, width, height } = img
  const colours = new Set()
  let bright = 0, sum = [0, 0, 0], n = 0
  for (let i = 0; i < data.length; i += bpp) {
    const [r, g, b] = [data[i], data[i + 1], data[i + 2]]
    colours.add((r >> 3 << 10) | (g >> 3 << 5) | (b >> 3))
    if (0.2126 * r + 0.7152 * g + 0.0722 * b > 140) bright++
    sum[0] += r; sum[1] += g; sum[2] += b; n++
  }
  const hueOf = (r, g, b) => (b > r + 20 && b > g + 20 ? 'blue' : r > b + 20 && r > g + 10 ? 'warm' : 'other')
  const hues = new Set()
  for (let i = 0; i < data.length; i += bpp) hues.add(hueOf(data[i], data[i + 1], data[i + 2]))
  return {
    pixels: n, colours: colours.size, bright,
    mean: sum.map((v) => Math.round(v / n)),
    hues: [...hues].join('+'),
    coverage: (bright / (width * height)).toFixed(3),
  }
}
const lum = (hex) => {
  const c = hex.match(/\w\w/g).map((h) => parseInt(h, 16) / 255)
    .map((v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4))
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]
}
const contrast = (a, b) => {
  const [x, y] = [lum(a), lum(b)].sort((m, n) => n - m)
  return ((x + 0.05) / (y + 0.05)).toFixed(2)
}

const proc = spawn(process.execPath, ['main.js'], {
  cwd: REPO, env: { ...process.env, PORT: String(PORT), DATA_FILE }, stdio: ['ignore', 'pipe', 'pipe'],
})
let log = ''
proc.stderr.on('data', (d) => { log += d })
await new Promise((r) => proc.stdout.once('data', r))

const browser = await chromium.launch({
  headless: true,
  executablePath: '/home/ian/.cache/ms-playwright/chromium-1228/chrome-linux64/chrome',
})
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } })
const page = await context.newPage()
const requests = []
page.on('request', (r) => requests.push(r.url()))
const consoleBad = []
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') consoleBad.push(m.text()) })
page.on('pageerror', (e) => consoleBad.push(String(e)))

await page.goto(URL, { waitUntil: 'load' })
await page.waitForFunction(() => (document.querySelector('#status')?.textContent ?? '').includes('Type to edit'))

// 1. no external assets: everything came from the app itself
check('no external assets (fonts/CDNs/images)', requests.every((u) => u.startsWith(URL)),
  requests.join(' '))

// 2. the stylesheet itself contains the required pieces
const css = await (await fetch(`${URL}/styles.css`)).text()
const keyframes = [...css.matchAll(/@keyframes\s+([\w-]+)/g)].map((m) => m[1])
check('keyframes present', ['drift-violet', 'drift-cyan', 'drift-magenta', 'shimmer', 'pulse', 'brighten'].every((k) => keyframes.includes(k)), keyframes.join(','))
check('reduced-motion block present', /prefers-reduced-motion:\s*reduce[\s\S]*animation:\s*none\s*!important/.test(css))
check('grain is an inline SVG feTurbulence data-URI', /url\("data:image\/svg\+xml[^"]*feTurbulence/.test(css))
check('vignette present', /radial-gradient\([^)]*transparent 45%[^)]*rgba\(0, 0, 0, 0?\.55\)/.test(css))
check('sub-640px blur reduced to 50px', /max-width:\s*640px[\s\S]*blur\(50px\)/.test(css))

// 3. computed styles at 1440x900
const cs = await page.evaluate(() => {
  const get = (sel) => {
    const el = document.querySelector(sel)
    const s = getComputedStyle(el)
    return { rect: el.getBoundingClientRect().toJSON(), s: { ...s } }
  }
  const layer = (sel) => {
    const s = getComputedStyle(document.querySelector(sel))
    return { pos: s.position, top: s.top, right: s.right, bottom: s.bottom, left: s.left, pe: s.pointerEvents, z: s.zIndex }
  }
  const blobs = [...document.querySelectorAll('.blob')].map((b) => {
    const s = getComputedStyle(b)
    return { filter: s.filter, opacity: s.opacity, blend: s.mixBlendMode, radius: s.borderRadius, dur: s.animationDuration, dir: s.animationDirection, wc: s.willChange, bg: s.backgroundColor }
  })
  const body = getComputedStyle(document.body)
  const main = getComputedStyle(document.querySelector('main'))
  const text = getComputedStyle(document.querySelector('#text'))
  const status = getComputedStyle(document.querySelector('#status'))
  const grainBefore = getComputedStyle(document.querySelector('.grain'), '::before')
  const grainAfter = getComputedStyle(document.querySelector('.grain'), '::after')
  const bg = getComputedStyle(document.querySelector('.bg'))
  return {
    viewport: { w: document.documentElement.clientWidth, h: document.documentElement.clientHeight },
    body: { minH: body.minHeight, display: body.display, place: body.placeItems, ov: body.overflow, margin: body.margin, font: body.fontFamily, scheme: getComputedStyle(document.documentElement).colorScheme },
    main: { width: main.width, pad: main.padding, align: main.textAlign },
    layers: ['.bg', '.aurora', '.grain'].map(layer),
    bgGrad: bg.backgroundImage,
    blobs,
    grain: { img: grainBefore.backgroundImage.slice(0, 40), op: grainBefore.opacity, vig: grainAfter.backgroundImage.slice(0, 30) },
    text: { size: text.fontSize, weight: text.fontWeight, ls: text.letterSpacing, lh: text.lineHeight, ws: text.whiteSpace, ow: text.overflowWrap,
      grad: text.backgroundImage, size2: text.backgroundSize, clip: text.webkitBackgroundClip || text.backgroundClip, fill: text.webkitTextFillColor,
      caret: text.caretColor, filter: text.filter, anim: text.animationName, dur: text.animationDuration, h: document.querySelector('#text').getBoundingClientRect().height },
    status: { pos: status.position, bottom: status.bottom, left: status.left, transform: status.transform, fs: status.fontSize, ls: status.letterSpacing, tt: status.textTransform, op: status.opacity, tr: status.transitionProperty, color: status.color },
    dot: getComputedStyle(document.querySelector('#status'), '::before').backgroundColor,
  }
})
check('canvas: 100svh grid, centred, no scroll margin', cs.body.minH === '900px' && cs.body.display === 'grid'
  && cs.body.place === 'center' && cs.body.ov === 'hidden' && cs.body.margin === '0px' && cs.body.scheme === 'dark',
  JSON.stringify(cs.body))
check('text container min(1100px,92vw) centred with clamp padding',
  cs.main.width === '1100px' && cs.main.align === 'center' && cs.main.pad === '64px', JSON.stringify(cs.main))
check('three stacked fixed background layers, non-interactive, z-index -1',
  cs.layers.length === 3 && cs.layers.every((l) => l.pos === 'fixed' && l.top === '0px' && l.right === '0px'
    && l.bottom === '0px' && l.left === '0px' && l.pe === 'none' && l.z === '-1'), JSON.stringify(cs.layers))
check('layer 1: base radial gradient', /radial-gradient/.test(cs.bgGrad) && /linear-gradient/.test(cs.bgGrad), cs.bgGrad.slice(0, 90))
check('layer 2: three blurred aurora blobs, screen blend, 0.5 opacity, slow alternate drift',
