    && cs.blobs.map((b) => b.bg).join(',') === 'rgb(109, 94, 252),rgb(34, 211, 238),rgb(244, 114, 182)',
  cs.blobs.map((b) => b.bg + ' ' + b.dur).join(' | '))
check('layer 3: grain data-URI at 0.05 + vignette', cs.grain.img.startsWith('url("data:image/svg+xml') && cs.grain.op === '0.05'
  && cs.grain.vig.startsWith('radial-gradient'), JSON.stringify(cs.grain))
