// 4. state dot colours change with state, and .saved drives the pulse animation
const dots = await page.evaluate(async () => {
  const el = document.querySelector('#status')
  const read = () => getComputedStyle(el, '::before').backgroundColor
  const out = {}
  const states = { saving: 'rgb(252, 211, 77)', saved: 'rgb(52, 211, 153)', error: 'rgb(248, 113, 113)' }
  for (const [cls, want] of Object.entries(states)) {
    el.classList.add(cls)
    const anim = getComputedStyle(el).animationName
    out[cls] = { dot: read(), anim, want }
    el.classList.remove(cls)
  }
  return out
})
check('state dots + pulse animation per state',
  Object.values(dots).every((d) => d.dot === d.want && (d.anim === 'none' || d.anim.includes('pulse'))), JSON.stringify(dots))

