await page.evaluate(() => document.querySelector('#text').blur())
await page.keyboard.press('Tab')
const ring = await page.evaluate(() => {
  const el = document.querySelector('#text')
  const s = getComputedStyle(el)
  return { matches: el.matches(':focus-visible'), w: s.outlineWidth, c: s.outlineColor, off: s.outlineOffset, style: s.outlineStyle }
})
