  `${textImg.width}x${textImg.height} colours=${tStats.colours} bright=${tStats.bright} coverage=${tStats.coverage}`)
check('headline shows a multi-hue gradient, not flat colour', tStats.hues.includes('warm') && tStats.hues.includes('blue'),
  `hues=${tStats.hues} mean=${tStats.mean.join(',')}`)

