const css6 = await page.evaluate(() => getComputedStyle(document.querySelector('#status')).color)
const statusHex = css6.match(/\d+/g).map((n) => n.toString(16).padStart(2, '0')).join('')
check('status text contrast >= 4.5:1 over the pill background',
  Number(contrast(statusHex, '070a14')) >= 4.5, `${statusHex} on ~#070a14 = ${contrast(statusHex, '070a14')}:1`)
check('headline gradient stops all >= 4.5:1 over the darkest backdrop',
  ['b7c3ff', '7dd3fc', 'f0abfc', 'ffffff'].every((h) => Number(contrast(h, '0a0a14')) >= 4.5),
  ['ffffff', 'b7c3ff', '7dd3fc', 'f0abfc'].map((h) => `${h}:${contrast(h, '0a0a14')}`).join(' '))

// 8. mobile viewport
await context.close()
const mob = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
const mp = await mob.newPage()
await mp.goto(URL, { waitUntil: 'load' })
await mp.waitForFunction(() => (document.querySelector('#status')?.textContent ?? '').includes('Type to edit'))
const mobInfo = await mp.evaluate(() => ({
  scrollW: document.documentElement.scrollWidth, clientW: document.documentElement.clientWidth,
  size: getComputedStyle(document.querySelector('#text')).fontSize,
  blur: getComputedStyle(document.querySelector('.blob')).filter,
  pill: document.querySelector('#status').getBoundingClientRect().toJSON(),
}))
check('mobile: zero horizontal scroll', mobInfo.scrollW <= mobInfo.clientW, `${mobInfo.scrollW} <= ${mobInfo.clientW}`)
check('mobile: clamp floor 3rem type + 50px blob blur', mobInfo.size === '48px' && mobInfo.blur === 'blur(50px)',
  JSON.stringify(mobInfo))
check('mobile: status pill fits the viewport', mobInfo.pill.x >= 0 && mobInfo.pill.right <= mobInfo.clientW,
  JSON.stringify(mobInfo.pill))
await mob.close()

// 9. full-page pixel sanity (background is dark and non-flat)
const full = decodePng(await page.screenshot())
const fStats = stats(full)
check('page background is dark and layered (not flat black)',
  fStats.mean[0] + fStats.mean[1] + fStats.mean[2] < 200 && fStats.colours > 500, JSON.stringify(fStats))

check('console stayed clean during the visual run', consoleBad.length === 0, consoleBad.join(' | '))
check('server stderr empty', log.trim() === '', log.trim())

await browser.close()
proc.kill('SIGTERM')
console.log(`\n${results.filter((r) => r.ok).length}/${results.length} visual checks passed`)
if (log.trim()) console.log('stderr:', log)
process.exit(results.every((r) => r.ok) ? 0 : 1)

